import React from 'react'
import { useLanguage } from '../../i18n/LanguageContext.jsx'
import { FIGURE_META } from './figureMeta.js'

/**
 * Figure 1 of the Home: an estimated response surface (conceptual, simulated
 * data). The drawing is a static SVG asset (public/figures, generated by
 * tools/figures/build-figures.mjs), not JavaScript. Its text is HTML, so it
 * uses the page's fonts and follows the language.
 *
 * Two drawings, one <img>: from 1180px the large surface with leader lines
 * (labels sit beside it, set by `--x` / `--y` from figureMeta); below that the
 * compact surface, clean, and the same list of labels reads as a legend
 * underneath, each item with a small key that matches what it names in the
 * drawing (no markers over the surface). The list is the figure's accessible
 * description in both.
 *
 * The image is the first thing the visitor sees, so it is never lazy: it loads
 * with high priority and carries its size, so nothing moves when it arrives.
 */
const HERO = FIGURE_META.hero
const PHONE = FIGURE_META.phone

export default function HeroFigure() {
  const { t } = useLanguage()
  const figure = 'home.hero.figure'

  return (
    <figure className="home-figure">
      <div className="home-figure__box">
        <picture>
          <source media="(min-width: 1180px)" srcSet="/figures/surface-hero.svg" width={HERO.W} height={HERO.H} />
          <img
            src="/figures/surface-compact.svg"
            width={PHONE.W}
            height={PHONE.H}
            alt={t(`${figure}.alt`)}
            fetchpriority="high"
            decoding="async"
          />
        </picture>
      </div>

      <ol className="home-figure__legend" aria-label={t(`${figure}.legendAria`)}>
        {HERO.labels.map((label, index) => (
          <li key={label.id} data-id={label.id} data-side={label.side} style={{ '--x': `${label.x}%`, '--y': `${label.y}%` }}>
            <span className="home-figure__n" aria-hidden="true" data-n={String(index + 1).padStart(2, '0')} data-d={index + 1} />
            <strong>{t(`${figure}.labels.${label.id}.title`)}</strong>
            <span className="home-figure__note">{t(`${figure}.labels.${label.id}.note`)}</span>
          </li>
        ))}
      </ol>

      <figcaption className="home-figure__caption">
        <span className="home-figure__caption-long">{t(`${figure}.caption`)}</span>
        <span className="home-figure__caption-short">{t(`${figure}.captionShort`)}</span>
      </figcaption>
    </figure>
  )
}
